CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "user_role" AS ENUM ('PARTICIPANT','ADMIN'); CREATE TYPE "account_status" AS ENUM ('ACTIVE','DISABLED'); CREATE TYPE "dataset_validation_status" AS ENUM ('PENDING','VALID','INVALID'); CREATE TYPE "instrument_type" AS ENUM ('EQUITY','INDEX','FUTURES','OPTIONS'); CREATE TYPE "instrument_status" AS ENUM ('ACTIVE','SUSPENDED','DELISTED'); CREATE TYPE "event_status" AS ENUM ('SETUP','READY','RUNNING','PAUSED','ENDED'); CREATE TYPE "simulation_status" AS ENUM ('STOPPED','RUNNING','PAUSED'); CREATE TYPE "day_status" AS ENUM ('PRE_OPEN','OPEN','CLOSED'); CREATE TYPE "market_status" AS ENUM ('PRE_OPEN','OPEN','PAUSED','HALTED','CLOSED'); CREATE TYPE "position_side" AS ENUM ('LONG','SHORT'); CREATE TYPE "order_side" AS ENUM ('BUY','SELL','CLOSE'); CREATE TYPE "order_status" AS ENUM ('PENDING','ACCEPTED','FILLED','REJECTED','FAILED','PARTIALLY_FILLED','CANCEL_REQUESTED','CANCELLED'); CREATE TYPE "ledger_reason" AS ENUM ('INITIAL_CAPITAL','ORDER_RESERVATION','ORDER_RESERVATION_RELEASE','ORDER_EXECUTION','REALIZED_PNL','FEE','ADMIN_ADJUSTMENT'); CREATE TYPE "news_type" AS ENUM ('MARKET_UPDATE','EVENT_UPDATE','ANNOUNCEMENT');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"participant_id" text NOT NULL UNIQUE,"display_name" text NOT NULL,"password_hash" text NOT NULL,"role" user_role NOT NULL DEFAULT 'PARTICIPANT',"account_status" account_status NOT NULL DEFAULT 'ACTIVE',"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "refresh_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL REFERENCES users(id),"token_hash" text NOT NULL UNIQUE,"expires_at" timestamptz NOT NULL,"revoked_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "datasets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"name" text NOT NULL,"version" text NOT NULL,"description" text,"checksum" text NOT NULL,"validation_status" dataset_validation_status NOT NULL DEFAULT 'PENDING',"total_days" integer NOT NULL CHECK (total_days > 0),"interval_seconds" integer NOT NULL DEFAULT 10 CHECK (interval_seconds > 0),"intervals_per_day" integer NOT NULL DEFAULT 72 CHECK (intervals_per_day > 0),"source_uri" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(name,version));
CREATE TABLE "instruments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"symbol" text NOT NULL UNIQUE,"name" text NOT NULL,"instrument_type" instrument_type NOT NULL,"exchange" text NOT NULL,"status" instrument_status NOT NULL DEFAULT 'ACTIVE',"tick_size" numeric(24,8) NOT NULL CHECK (tick_size > 0),"lot_size" integer NOT NULL CHECK (lot_size > 0),"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "dataset_candles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"dataset_id" uuid NOT NULL REFERENCES datasets(id),"instrument_id" uuid NOT NULL REFERENCES instruments(id),"trading_day" integer NOT NULL CHECK (trading_day > 0),"interval_index" integer NOT NULL CHECK (interval_index >= 0),"timestamp" timestamptz NOT NULL,"open" numeric(24,8) NOT NULL,"high" numeric(24,8) NOT NULL,"low" numeric(24,8) NOT NULL,"close" numeric(24,8) NOT NULL,"volume" integer NOT NULL CHECK (volume >= 0), UNIQUE(dataset_id,instrument_id,trading_day,interval_index), CHECK (low <= open AND low <= close AND high >= open AND high >= close));
CREATE TABLE "events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"dataset_id" uuid REFERENCES datasets(id),"status" event_status NOT NULL DEFAULT 'SETUP',"total_simulation_days" integer CHECK (total_simulation_days IS NULL OR total_simulation_days > 0),"simulation_speed" integer NOT NULL DEFAULT 1 CHECK (simulation_speed > 0),"config_locked" boolean NOT NULL DEFAULT false,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),"ended_at" timestamptz);
CREATE TABLE "event_instruments" ("event_id" uuid NOT NULL REFERENCES events(id),"instrument_id" uuid NOT NULL REFERENCES instruments(id),"created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,instrument_id));
CREATE TABLE "simulation_states" ("event_id" uuid PRIMARY KEY REFERENCES events(id),"status" simulation_status NOT NULL DEFAULT 'STOPPED',"day_status" day_status NOT NULL DEFAULT 'PRE_OPEN',"market_status" market_status NOT NULL DEFAULT 'PRE_OPEN',"simulation_day" integer NOT NULL DEFAULT 0 CHECK (simulation_day >= 0),"interval_index" integer NOT NULL DEFAULT 0 CHECK (interval_index >= 0),"simulated_at" timestamptz,"last_committed_at" timestamptz,"lease_owner" text,"lease_expires_at" timestamptz,"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "event_participants" ("event_id" uuid NOT NULL REFERENCES events(id),"user_id" uuid NOT NULL REFERENCES users(id),"joined_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,user_id));
CREATE TABLE "portfolios" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"event_id" uuid NOT NULL REFERENCES events(id),"user_id" uuid NOT NULL REFERENCES users(id),"starting_capital" numeric(24,8) NOT NULL,"available_cash" numeric(24,8) NOT NULL CHECK (available_cash >= 0),"reserved_cash" numeric(24,8) NOT NULL DEFAULT 0 CHECK (reserved_cash >= 0),"realized_pnl" numeric(24,8) NOT NULL DEFAULT 0,"daily_pnl" numeric(24,8) NOT NULL DEFAULT 0,"updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id));
CREATE TABLE "positions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"event_id" uuid NOT NULL REFERENCES events(id),"user_id" uuid NOT NULL REFERENCES users(id),"instrument_id" uuid NOT NULL REFERENCES instruments(id),"side" position_side,"quantity" integer NOT NULL DEFAULT 0 CHECK (quantity >= 0),"average_entry_price" numeric(24,8),"realized_pnl" numeric(24,8) NOT NULL DEFAULT 0,"opened_at" timestamptz,"updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id,instrument_id));
CREATE TABLE "orders" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"event_id" uuid NOT NULL REFERENCES events(id),"user_id" uuid NOT NULL REFERENCES users(id),"instrument_id" uuid NOT NULL REFERENCES instruments(id),"client_order_id" text NOT NULL,"side" order_side NOT NULL,"quantity" integer NOT NULL CHECK (quantity > 0),"filled_quantity" integer NOT NULL DEFAULT 0 CHECK (filled_quantity >= 0 AND filled_quantity <= quantity),"order_type" text NOT NULL DEFAULT 'MARKET',"status" order_status NOT NULL DEFAULT 'PENDING',"average_price" numeric(24,8),"idempotency_key" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,user_id,client_order_id), UNIQUE(user_id,idempotency_key));
CREATE TABLE "executions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"order_id" uuid NOT NULL REFERENCES orders(id),"quantity" integer NOT NULL CHECK (quantity > 0),"price" numeric(24,8) NOT NULL CHECK (price > 0),"executed_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "portfolio_ledger_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"portfolio_id" uuid NOT NULL REFERENCES portfolios(id),"order_id" uuid REFERENCES orders(id),"reason" ledger_reason NOT NULL,"amount" numeric(24,8) NOT NULL,"balance_after" numeric(24,8) NOT NULL,"metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "idempotency_records" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL REFERENCES users(id),"key" text NOT NULL,"request_fingerprint" text NOT NULL,"response_status" integer NOT NULL,"response_body" jsonb NOT NULL,"expires_at" timestamptz NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,key));
CREATE TABLE "news" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"public_id" text NOT NULL UNIQUE,"event_id" uuid REFERENCES events(id),"author_user_id" uuid NOT NULL REFERENCES users(id),"type" news_type NOT NULL,"title" text NOT NULL,"body" text NOT NULL,"audience" text NOT NULL,"published_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "leaderboard_snapshots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"event_id" uuid NOT NULL REFERENCES events(id),"version" integer NOT NULL,"simulation_day" integer NOT NULL,"snapshot" jsonb NOT NULL,"as_of" timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,version));
CREATE TABLE "audit_logs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"actor_user_id" uuid REFERENCES users(id),"action" text NOT NULL,"resource_type" text NOT NULL,"resource_id" text NOT NULL,"previous_state" jsonb,"new_state" jsonb,"request_id" text NOT NULL,"ip_address" text,"user_agent" text,"metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "outbox_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"event_type" text NOT NULL,"aggregate_type" text NOT NULL,"aggregate_id" text NOT NULL,"payload" jsonb NOT NULL,"published_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "orders_user_created_at_idx" ON orders(user_id,created_at DESC); CREATE INDEX "dataset_candles_lookup_idx" ON dataset_candles(dataset_id,instrument_id,timestamp); CREATE INDEX "audit_logs_resource_idx" ON audit_logs(resource_type,resource_id,created_at DESC); CREATE INDEX "outbox_unpublished_idx" ON outbox_events(created_at) WHERE published_at IS NULL;
